mapper.select:
SELECT DISTINCT T.TREE_ID treeId, T.P_ID pId, T.TREE_NAME treeName, T.FLAG, b.rep_order repOrder FROM rep_tree T LEFT JOIN REP_INFO B ON T.TREE_ID=B.REP_ID LEFT JOIN rep_power p ON p.report_id= t.tree_id WHERE 1=1 AND (T.FLAG IS NULL OR T.FLAG='C' OR B.REPORT_TYPE='Y')
and T.TREE_ID = #{pId,jdbcType=VARCHAR}
and T.P_ID = #{treeId,jdbcType=VARCHAR}
and T.TREE_NAME like '%'||#{paraTreeName}||'%'
AND ( (T.FLAG != 'Y' OR T.FLAG='C' or T.FLAG is null)/*Y以外（为节点）则全部查出*/ OR(B.REPORT_TYPE='Y' and p.ID IN
#{item}
)/*Y为报表需要根据权限来过滤，REPORT_TYPE='Y'表示需要展示*/ )
ORDER BY B.REP_ORDER

select TREE_ID treeId, P_ID pId, TREE_NAME treeName, FLAG from rep_tree WHERE 1=1
AND P_ID=#{PId,jdbcType=VARCHAR}
AND TREE_ID=#{treeId,jdbcType=VARCHAR}
